	@Test
	void publicAwaitIncludesTheDeferredProviderPublication() throws Exception {
		seedSnapshot();
		try (HeldProvider fixture = new HeldProvider()) {
			var estimator = fixture.store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.rebuild();
			assertTrue(estimator.isReadyNonBlocking(), "the caller's rebuilt estimator must already be ready");
			assertFalse(fixture.store.awaitSketchesReady(0L, TimeUnit.NANOSECONDS),
					"public readiness must include the still pending owner publication");
			fixture.release.countDown();
			assertTrue(fixture.store.awaitSketchesReady(30L, TimeUnit.SECONDS));
			assertEquals("READY", fixture.store.getStartupStatus().auxiliaryMaintenance());
		}
	}

	@Test
	void publicAwaitTimeoutAndInterruptionLeaveTheOwnerJobRunning() throws Exception {
		seedSnapshot();
		try (HeldProvider fixture = new HeldProvider()) {
			assertFalse(fixture.store.awaitSketchesReady(1L, TimeUnit.MILLISECONDS));
			AtomicReference<Throwable> failure = new AtomicReference<>();
			Thread waiter = Thread.ofPlatform().start(() -> {
				try {
					fixture.store.awaitSketchesReady(30L, TimeUnit.SECONDS);
				} catch (Throwable problem) {
					failure.set(problem);
				}
			});
			try {
				while (waiter.isAlive() && waiter.getState() != Thread.State.TIMED_WAITING) {
					Thread.yield();
				}
				assertTrue(waiter.isAlive(), "the public waiter must still be blocked on owner completion");
				waiter.interrupt();
				waiter.join(TimeUnit.SECONDS.toMillis(30L));
				assertFalse(waiter.isAlive());
				assertInstanceOf(InterruptedException.class, failure.get());
				assertEquals("RUNNING", fixture.store.getStartupStatus().auxiliaryMaintenance());
			} finally {
				fixture.release.countDown();
				waiter.interrupt();
				waiter.join(TimeUnit.SECONDS.toMillis(30L));
			}
			assertTrue(fixture.store.awaitSketchesReady(30L, TimeUnit.SECONDS),
					"a timed out or interrupted caller must not cancel optional initialization");
		}
	}

	@Test
	void startupStatusIncludesARealHeldSketchRefresh() throws Exception {
		seedSnapshot();
		try (HeldProvider fixture = new HeldProvider()) {
			fixture.release.countDown();
			LmdbTestUtil.awaitPostReadyInitialization(fixture.store, 30L, TimeUnit.SECONDS);
			assertTrue(fixture.store.awaitIndexRebuild(30L, TimeUnit.SECONDS));
			var estimator = fixture.store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			fixture.holdRefresh.set(true);
			estimator.discardAndMarkForRebuild();
			estimator.startBackgroundRefresh(3);
			assertTrue(fixture.refreshEntered.await(30L, TimeUnit.SECONDS));
			assertEquals("READY", fixture.store.getStartupStatus().auxiliaryMaintenance());
			assertTrue(fixture.store.getStartupStatus().optionalMaintenancePending(),
					"a running sketch refresh remains pending after its owner initialization completes");
			fixture.releaseRefresh.countDown();
			assertTrue(fixture.store.awaitSketchesReady(30L, TimeUnit.SECONDS));
			estimator.stop();
			assertFalse(fixture.store.getStartupStatus().optionalMaintenancePending(),
					"a stopped optional worker must not remain pending indefinitely");
		}
	}

