	@Test
	void unpublishedStaleCleanupDoesNotHoldTheOrdinaryWriterFence() throws Exception {
		seedSnapshot();
		try (HeldProvider fixture = new HeldProvider()) {
			assertEquals(10L, fixture.loaded.get().getFilterObservationCount(PATTERN, "loaded-filter"));
			addStatement(fixture.repository, "make-loaded-snapshot-stale");
			fixture.holdDiscard.set(true);
			fixture.release.countDown();
			assertTrue(fixture.discardEntered.await(30L, TimeUnit.SECONDS));
			CompletableFuture<Void> committed = new CompletableFuture<>();
			CountDownLatch writerFinished = new CountDownLatch(1);
			Thread writer = Thread.ofPlatform().start(() -> {
				try {
					addStatement(fixture.repository, "during-unpublished-discard");
					committed.complete(null);
				} catch (Throwable failure) {
					committed.completeExceptionally(failure);
				} finally {
					writerFinished.countDown();
				}
			});
			try {
				assertTrue(writerFinished.await(10L, TimeUnit.SECONDS),
						"ordinary native commit must finish while unpublished derived cleanup is held");
				committed.get(10L, TimeUnit.SECONDS);
				assertFalse(fixture.store.awaitSketchesReady(0L, TimeUnit.NANOSECONDS));
			} finally {
				fixture.releaseDiscard.countDown();
				writer.join(TimeUnit.SECONDS.toMillis(30L));
				assertFalse(writer.isAlive());
			}
			LmdbTestUtil.awaitPostReadyInitialization(fixture.store, 30L, TimeUnit.SECONDS);
			assertEquals(1, fixture.discards.get(), "an already invalidated unpublished provider needs no reload loop");
			assertEquals(-1L, fixture.loaded.get().getFilterObservationCount(PATTERN, "loaded-filter"),
					"intervening commits must never republish the stale loaded observations");
		}
	}

	@Test
	void benchmarkBulkPreparationWaitsBeforeStoppingTheEstimator() throws Exception {
		seedSnapshot();
		try (HeldProvider fixture = new HeldProvider()) {
			CompletableFuture<Void> prepared = new CompletableFuture<>();
			Thread caller = Thread.ofPlatform().start(() -> {
				try {
					BenchmarkJoinEstimatorSupport.prepareEstimatorForBulkLoad(fixture.repository, fixture.store);
					prepared.complete(null);
				} catch (Throwable failure) {
					prepared.completeExceptionally(failure);
				}
			});
			try {
				boolean inOwnerWait = false;
				while (caller.isAlive() && !inOwnerWait) {
					for (StackTraceElement frame : caller.getStackTrace()) {
						inOwnerWait |= frame.getClassName().equals(LmdbTestUtil.class.getName())
								&& frame.getMethodName().equals("awaitPostReadyInitialization");
					}
					Thread.yield();
				}
				assertTrue(inOwnerWait, "bulk preparation must reach the actual deferred owner wait");
				assertFalse(prepared.isDone(), "bulk preparation must not stop an estimator still being installed");
			} finally {
				fixture.release.countDown();
				prepared.get(30L, TimeUnit.SECONDS);
				caller.join(TimeUnit.SECONDS.toMillis(30L));
				assertFalse(caller.isAlive());
			}
		}
	}

	private void seedSnapshot() throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30L, TimeUnit.SECONDS);
			addStatement(repository, "seed");
			var estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.rebuild();
			assertTrue(estimator.isReadyNonBlocking());
			estimator.persistIfDirty();
		} finally {
			repository.shutDown();
		}
	}

