	private static void addStatement(SailRepository repository, String suffix) {
		try (var connection = repository.getConnection()) {
			var values = SimpleValueFactory.getInstance();
			connection.add(values.createIRI("urn:sketch-install:" + suffix),
					values.createIRI("urn:sketch-install:predicate"), values.createLiteral(suffix));
		}
	}

	private final class HeldProvider implements AutoCloseable {
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);
		private final CountDownLatch refreshEntered = new CountDownLatch(1);
		private final CountDownLatch releaseRefresh = new CountDownLatch(1);
		private final AtomicBoolean holdRefresh = new AtomicBoolean();
		private final AtomicBoolean holdDiscard = new AtomicBoolean();
		private final CountDownLatch discardEntered = new CountDownLatch(1);
		private final CountDownLatch releaseDiscard = new CountDownLatch(1);
		private final AtomicInteger discards = new AtomicInteger();
		private final boolean fail;
		private final AtomicReference<LmdbFilterSelectivityStats> loaded = new AtomicReference<>();
		private final LmdbStore store = new LmdbStore(directory.toFile(), config()) {
			@Override
			LmdbSailStore createBackingStore(File data, StoreProperties properties, LmdbStoreConfig settings,
					boolean sketches) throws IOException {
				LmdbSailStore.FilterSelectivityStatsFactory stats = (path, triples, values, enabled, millis, rows,
						raw) -> {
					LmdbFilterSelectivityStats result = new LmdbFilterSelectivityStats(path, triples, values,
							enabled, millis, rows, raw) {
						@Override
						void recordStoreMutation() {
							discards.incrementAndGet();
							if (holdDiscard.compareAndSet(true, false)) {
								discardEntered.countDown();
								try {
									releaseDiscard.await();
								} catch (InterruptedException interrupted) {
									Thread.currentThread().interrupt();
									throw new IllegalStateException(interrupted);
								}
							}
							super.recordStoreMutation();
						}
					};
					result.recordFilterOutcome(PATTERN, "loaded-filter", 1L, 9L);
					loaded.set(result);
					return result;
				};
				return new LmdbSailStore(data, properties, settings, sketches, null, TripleStore::new,
						PersistentSetFactory::new, stats) {
					@Override
					void beforeSketchProviderPublicationForTest() {
						entered.countDown();
						try {
							release.await();
							if (fail) {
								throw new IllegalStateException("controlled sketch provider installation failure");
							}
						} catch (InterruptedException interrupted) {
							Thread.currentThread().interrupt();
							throw new IllegalStateException(interrupted);
						}
					}

					@Override
					void beforeSketchRefreshReadForTest() {
						if (holdRefresh.get()) {
							refreshEntered.countDown();
							try {
								releaseRefresh.await();
							} catch (InterruptedException interrupted) {
								Thread.currentThread().interrupt();
								throw new IllegalStateException(interrupted);
							}
						}
					}
				};
			}
		};
		private final SailRepository repository = new SailRepository(store);

		private HeldProvider() throws Exception {
			this(false);
		}

		private HeldProvider(boolean fail) throws Exception {
			this.fail = fail;
			repository.init();
			assertTrue(entered.await(30L, TimeUnit.SECONDS));
		}

		@Override
		public void close() {
			release.countDown();
			releaseRefresh.countDown();
			releaseDiscard.countDown();
			repository.shutDown();
		}
	}
